-- Speglar det som lades på databasen 2026-09-15 via apply_migration i fyra delar:
--   lesh_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   lesh_order_code_from_catalogue_part_02  (värdelista, rensning, regler 1–20)
--   lesh_order_code_from_catalogue_part_03  (regler 21–43, dokumentkarta, produktspecar)
--   lesh_order_code_from_catalogue_part_04  (slaglängdens etiketter "Slag 50 mm" -- "50 mm slag" klipptes
--                                            av stripLeadingCode; den här filen bär de rättade etiketterna)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts lesh):
--   regler  43   md5 5cde518332dbfd80b10d2f20d136b37a   villkor ecacfdfbf752e846dc96613eb23a545d
--   värden  54   md5 75ed04cc96802f90351e350571bc4af3
--   schema       md5 f10bdbe0c61dab79bf8211c5940dcb18
-- Verifierat live: /sv/configurator/lesh bygger LESH25REJ-50-R1CD17T (nyckelns exempel, sida 705),
-- kräver monteringen 7/8 för JXC innan koden är klar och stoppar låset B på LESH16RJ-50 (sida 715).
--
-- LESH: beställnyckeln enligt SMC Slide Tables LES/LESH Series (sida 705 och 715).
-- GENERERAD ur src/lib/catalog/lesh.ts -- redigera inte för hand.
--
-- Rättar familjen lesh, som hade mallen 'LESH-{size}-{stroke_mm}-{motor_mount}'
-- med fritext (inline/parallel, low/standard/high). SMC:s kod är
-- LESH{storlek}{fäste}{motor}{stigning}-{slag}{lås}{kropp}{hållare}-{kabel}{styrenhet}{I/O-kabel}{montering}{tillbehör},
-- t.ex. LESH25REJ-50-R1CD17T (sida 705). Motortyp, lås, dammskydd, sidohållare,
-- kabel och styrenhet (JXC/LEC, en nyckel i nyckeln) fanns inte alls.
--
-- SMC-LESH får katalogens slag, repeternoggrannhet och motorer.

begin;

create schema if not exists backup;
create table if not exists backup.lesh_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'lesh'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'lesh'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'lesh';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-LESH-V1', '{"version":"1.0","steps":[{"id":"size","step":1,"title_sv":"Storlek","title_en":"Size","required":true,"type":"single_select","options":[{"v":"8","label":"Storlek 8 (motor 20, slag 50 eller 75)"},{"v":"16","label":"Storlek 16 (motor 28, slag 50 eller 100)"},{"v":"25","label":"Storlek 25 (motor 42, slag 50, 100 eller 150)"}]},{"id":"mount","step":2,"title_sv":"Motorns placering","title_en":"Motor mounting position","required":true,"type":"single_select","options":[{"v":"R","label":"Basutförande: motorn parallellt med bordet (R)"},{"v":"L","label":"Symmetriskt utförande: motorn parallellt, spegelvänt (L)"},{"v":"D","label":"Motorn i linje bakom bordet (D)"}]},{"id":"motor","step":3,"title_sv":"Motortyp (standard är stegmotor 24 V DC, inkrementell)","title_en":"Motor type (incremental step motor 24 VDC is standard)","required":false,"type":"single_select","options":[{"v":"A","label":"Servomotor 24 V DC, inkrementell (styrenhet LECA6)"},{"v":"E","label":"Batterilös absolut stegmotor 24 V DC (bara storlek 25; styrenhet JXC)"}]},{"id":"lead","step":4,"title_sv":"Stigning","title_en":"Lead","required":true,"type":"single_select","options":[{"v":"J","label":"Hög stigning: 8/10/16 mm för storlek 8/16/25"},{"v":"K","label":"Låg stigning: 4/5/8 mm för storlek 8/16/25"}]},{"id":"stroke","step":5,"title_sv":"Slaglängd","title_en":"Stroke","required":true,"type":"single_select","options":[{"v":"50","label":"Slag 50 mm"},{"v":"75","label":"Slag 75 mm (storlek 8)"},{"v":"100","label":"Slag 100 mm (storlek 16 och 25)"},{"v":"150","label":"Slag 150 mm (storlek 25)"}]},{"id":"lock","step":6,"title_sv":"Motortillval","title_en":"Motor option","required":false,"type":"single_select","options":[{"v":"B","label":"Med lås (omagnetiserande, hållkraft 24/300/500 N)"}]},{"id":"body","step":7,"title_sv":"Kroppstillval","title_en":"Body option","required":false,"type":"single_select","options":[{"v":"S","label":"Dammskyddad: avstrykare på stångkåpan, packningar i ändkåporna (R/L ≈ IP5X)"}]},{"id":"holder","step":8,"title_sv":"Montering","title_en":"Mounting","required":false,"type":"single_select","options":[{"v":"H","label":"Med sidohållare, 4 st (bara D-typ)"}]},{"id":"cable","step":9,"title_sv":"Aktuatorkabel","title_en":"Actuator cable type/length","required":false,"type":"single_select","options":[{"v":"S1","label":"Standardkabel 1,5 m (bara stegmotor, fast förlagd)"},{"v":"S3","label":"Standardkabel 3 m (bara stegmotor, fast förlagd)"},{"v":"S5","label":"Standardkabel 5 m (bara stegmotor, fast förlagd)"},{"v":"R1","label":"Robotkabel 1,5 m"},{"v":"R3","label":"Robotkabel 3 m"},{"v":"R5","label":"Robotkabel 5 m"},{"v":"R8","label":"Robotkabel 8 m (på beställning)"},{"v":"RA","label":"Robotkabel 10 m (på beställning)"},{"v":"RB","label":"Robotkabel 15 m (på beställning)"},{"v":"RC","label":"Robotkabel 20 m (på beställning)"}]},{"id":"ctrl","step":10,"title_sv":"Styrenhet (aktuator och styrenhet säljs som ett paket)","title_en":"Controller (actuator and controller are sold as a package)","required":false,"type":"single_select","options":[{"v":"C51","label":"JXC51: parallell I/O NPN, stegdata"},{"v":"C61","label":"JXC61: parallell I/O PNP, stegdata"},{"v":"CE1","label":"JXCE1: EtherCAT"},{"v":"CEF","label":"JXCEF: EtherCAT med STO"},{"v":"C91","label":"JXC91: EtherNet/IP"},{"v":"C9F","label":"JXC9F: EtherNet/IP med STO"},{"v":"CP1","label":"JXCP1: PROFINET"},{"v":"CPF","label":"JXCPF: PROFINET med STO"},{"v":"CD1","label":"JXCD1: DeviceNet"},{"v":"CL1","label":"JXCL1: IO-Link"},{"v":"CLF","label":"JXCLF: IO-Link med STO"},{"v":"CM1","label":"JXCM1: CC-Link"},{"v":"6N","label":"LECA6 NPN: stegdata, för servomotorn"},{"v":"6P","label":"LECA6 PNP: stegdata, för servomotorn"},{"v":"AN","label":"LECPA NPN: pulsingång, för stegmotorn (inkrementell)"},{"v":"AP","label":"LECPA PNP: pulsingång, för stegmotorn (inkrementell)"}]},{"id":"io_cable","step":11,"title_sv":"I/O-kabel (LEC)","title_en":"I/O cable (LEC)","required":false,"type":"single_select","options":[{"v":"1","label":"I/O-kabel 1,5 m (LEC)"},{"v":"3","label":"I/O-kabel 3 m (LEC)"},{"v":"5","label":"I/O-kabel 5 m (LEC)"}]},{"id":"ctrl_mount","step":12,"title_sv":"Styrenhetens montering","title_en":"Controller mounting","required":false,"type":"single_select","options":[{"v":"7","label":"Skruvmontering (JXC)"},{"v":"8","label":"DIN-skena (JXC; skenan beställs separat)"},{"v":"D","label":"DIN-skena (LEC; skenan beställs separat)"}]},{"id":"ctrl_acc","step":13,"title_sv":"Styrenhetens tillbehör (JXC)","title_en":"Controller accessory (JXC)","required":false,"type":"single_select","options":[{"v":"S","label":"Rak kommunikationsplugg (DeviceNet, CC-Link)"},{"v":"T","label":"T-grenad kommunikationsplugg (DeviceNet, CC-Link)"},{"v":"1","label":"I/O-kabel 1,5 m (JXC51/61)"},{"v":"3","label":"I/O-kabel 3 m (JXC51/61)"},{"v":"5","label":"I/O-kabel 5 m (JXC51/61)"}]}]}'::jsonb,
        'SMC LESH elektriskt slidbord med hög styvhet', 'SMC LESH electric slide table, high rigidity type', 'electric-actuator')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Elektriskt slidbord med hög styvhet, storlek 8–25, med styrenhet',
  description = 'SMC LESH electric slide table, high rigidity type: sizes 8, 16 and 25, strokes 50–150 mm, step motor (incremental or battery-less absolute) or servo motor 24 VDC, JXC or LEC controller in the same part number.',
  stroke_min_mm = 50,
  stroke_max_mm = 150,
  order_code_template = 'LESH{size}{mount}{motor}{lead}-{stroke}{lock}{body}{holder}-{cable}{ctrl}{io_cable}{ctrl_mount}{ctrl_acc}',
  rules_schema_id = 'SCHEMA-LESH-V1'
where slug = 'lesh';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'lesh';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'lesh';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"size","label":"Storlek","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"mount","label":"Motorns placering","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"motor","label":"Motortyp (standard är stegmotor 24 V DC, inkrementell)","param_type":"select","sort_order":3,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Stigning","param_type":"select","sort_order":4,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke","label":"Slaglängd","param_type":"select","sort_order":5,"required":true,"min_value":null,"max_value":null},{"param_key":"lock","label":"Motortillval","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"body","label":"Kroppstillval","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"holder","label":"Montering","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"cable","label":"Aktuatorkabel","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"ctrl","label":"Styrenhet (aktuator och styrenhet säljs som ett paket)","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null},{"param_key":"io_cable","label":"I/O-kabel (LEC)","param_type":"select","sort_order":11,"required":false,"min_value":null,"max_value":null},{"param_key":"ctrl_mount","label":"Styrenhetens montering","param_type":"select","sort_order":12,"required":false,"min_value":null,"max_value":null},{"param_key":"ctrl_acc","label":"Styrenhetens tillbehör (JXC)","param_type":"select","sort_order":13,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'lesh';

insert into configurator_param_values (param_id, code, label, sort_order)
select p.id, r.code, r.label, r.sort_order
from jsonb_to_recordset('[{"param_key":"size","code":"8","label":"Storlek 8 (motor 20, slag 50 eller 75)","sort_order":0},{"param_key":"size","code":"16","label":"Storlek 16 (motor 28, slag 50 eller 100)","sort_order":1},{"param_key":"size","code":"25","label":"Storlek 25 (motor 42, slag 50, 100 eller 150)","sort_order":2},{"param_key":"mount","code":"R","label":"Basutförande: motorn parallellt med bordet (R)","sort_order":0},{"param_key":"mount","code":"L","label":"Symmetriskt utförande: motorn parallellt, spegelvänt (L)","sort_order":1},{"param_key":"mount","code":"D","label":"Motorn i linje bakom bordet (D)","sort_order":2},{"param_key":"motor","code":"A","label":"Servomotor 24 V DC, inkrementell (styrenhet LECA6)","sort_order":0},{"param_key":"motor","code":"E","label":"Batterilös absolut stegmotor 24 V DC (bara storlek 25; styrenhet JXC)","sort_order":1},{"param_key":"lead","code":"J","label":"Hög stigning: 8/10/16 mm för storlek 8/16/25","sort_order":0},{"param_key":"lead","code":"K","label":"Låg stigning: 4/5/8 mm för storlek 8/16/25","sort_order":1},{"param_key":"stroke","code":"50","label":"Slag 50 mm","sort_order":0},{"param_key":"stroke","code":"75","label":"Slag 75 mm (storlek 8)","sort_order":1},{"param_key":"stroke","code":"100","label":"Slag 100 mm (storlek 16 och 25)","sort_order":2},{"param_key":"stroke","code":"150","label":"Slag 150 mm (storlek 25)","sort_order":3},{"param_key":"lock","code":"B","label":"Med lås (omagnetiserande, hållkraft 24/300/500 N)","sort_order":0},{"param_key":"body","code":"S","label":"Dammskyddad: avstrykare på stångkåpan, packningar i ändkåporna (R/L ≈ IP5X)","sort_order":0},{"param_key":"holder","code":"H","label":"Med sidohållare, 4 st (bara D-typ)","sort_order":0},{"param_key":"cable","code":"S1","label":"Standardkabel 1,5 m (bara stegmotor, fast förlagd)","sort_order":0},{"param_key":"cable","code":"S3","label":"Standardkabel 3 m (bara stegmotor, fast förlagd)","sort_order":1},{"param_key":"cable","code":"S5","label":"Standardkabel 5 m (bara stegmotor, fast förlagd)","sort_order":2},{"param_key":"cable","code":"R1","label":"Robotkabel 1,5 m","sort_order":3},{"param_key":"cable","code":"R3","label":"Robotkabel 3 m","sort_order":4},{"param_key":"cable","code":"R5","label":"Robotkabel 5 m","sort_order":5},{"param_key":"cable","code":"R8","label":"Robotkabel 8 m (på beställning)","sort_order":6},{"param_key":"cable","code":"RA","label":"Robotkabel 10 m (på beställning)","sort_order":7},{"param_key":"cable","code":"RB","label":"Robotkabel 15 m (på beställning)","sort_order":8},{"param_key":"cable","code":"RC","label":"Robotkabel 20 m (på beställning)","sort_order":9},{"param_key":"ctrl","code":"C51","label":"JXC51: parallell I/O NPN, stegdata","sort_order":0},{"param_key":"ctrl","code":"C61","label":"JXC61: parallell I/O PNP, stegdata","sort_order":1},{"param_key":"ctrl","code":"CE1","label":"JXCE1: EtherCAT","sort_order":2},{"param_key":"ctrl","code":"CEF","label":"JXCEF: EtherCAT med STO","sort_order":3},{"param_key":"ctrl","code":"C91","label":"JXC91: EtherNet/IP","sort_order":4},{"param_key":"ctrl","code":"C9F","label":"JXC9F: EtherNet/IP med STO","sort_order":5},{"param_key":"ctrl","code":"CP1","label":"JXCP1: PROFINET","sort_order":6},{"param_key":"ctrl","code":"CPF","label":"JXCPF: PROFINET med STO","sort_order":7},{"param_key":"ctrl","code":"CD1","label":"JXCD1: DeviceNet","sort_order":8},{"param_key":"ctrl","code":"CL1","label":"JXCL1: IO-Link","sort_order":9},{"param_key":"ctrl","code":"CLF","label":"JXCLF: IO-Link med STO","sort_order":10},{"param_key":"ctrl","code":"CM1","label":"JXCM1: CC-Link","sort_order":11},{"param_key":"ctrl","code":"6N","label":"LECA6 NPN: stegdata, för servomotorn","sort_order":12},{"param_key":"ctrl","code":"6P","label":"LECA6 PNP: stegdata, för servomotorn","sort_order":13},{"param_key":"ctrl","code":"AN","label":"LECPA NPN: pulsingång, för stegmotorn (inkrementell)","sort_order":14},{"param_key":"ctrl","code":"AP","label":"LECPA PNP: pulsingång, för stegmotorn (inkrementell)","sort_order":15},{"param_key":"io_cable","code":"1","label":"I/O-kabel 1,5 m (LEC)","sort_order":0},{"param_key":"io_cable","code":"3","label":"I/O-kabel 3 m (LEC)","sort_order":1},{"param_key":"io_cable","code":"5","label":"I/O-kabel 5 m (LEC)","sort_order":2},{"param_key":"ctrl_mount","code":"7","label":"Skruvmontering (JXC)","sort_order":0},{"param_key":"ctrl_mount","code":"8","label":"DIN-skena (JXC; skenan beställs separat)","sort_order":1},{"param_key":"ctrl_mount","code":"D","label":"DIN-skena (LEC; skenan beställs separat)","sort_order":2},{"param_key":"ctrl_acc","code":"S","label":"Rak kommunikationsplugg (DeviceNet, CC-Link)","sort_order":0},{"param_key":"ctrl_acc","code":"T","label":"T-grenad kommunikationsplugg (DeviceNet, CC-Link)","sort_order":1},{"param_key":"ctrl_acc","code":"1","label":"I/O-kabel 1,5 m (JXC51/61)","sort_order":2},{"param_key":"ctrl_acc","code":"3","label":"I/O-kabel 3 m (JXC51/61)","sort_order":3},{"param_key":"ctrl_acc","code":"5","label":"I/O-kabel 5 m (JXC51/61)","sort_order":4}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'lesh';

delete from config_rules where schema_id = 'SCHEMA-LESH-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-LESH-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"motor"},"E"]},{"in":[{"var":"size"},["8","16"]]}]},"message_sv":"Batterilös absolut E finns bara i storlek 25, inte 8 och 16 (sida 705).","message_en":"The battery-less absolute E exists only in size 25, not 8 and 16 (page 705).","goto_step":"lesh-motor"},{"severity":"error","if_json":{"and":[{"==":[{"var":"motor"},"A"]},{"==":[{"var":"mount"},"D"]},{"==":[{"var":"size"},"25"]}]},"message_sv":"LESH25DA finns inte — servomotorn i storlek 25 bara med fäste R eller L (sida 716, not 1).","message_en":"LESH25DA is not available — the servo motor in size 25 only with mounting R or L (page 716, note 1).","goto_step":"lesh-mount"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"8"]},{"in":[{"var":"stroke"},["100","150"]]}]},"message_sv":"Storlek 8 finns med slag 50 eller 75 mm (sida 715).","message_en":"Size 8 exists with strokes 50 or 75 mm (page 715).","goto_step":"lesh-stroke"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"16"]},{"in":[{"var":"stroke"},["75","150"]]}]},"message_sv":"Storlek 16 finns med slag 50 eller 100 mm (sida 715).","message_en":"Size 16 exists with strokes 50 or 100 mm (page 715).","goto_step":"lesh-stroke"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"25"]},{"in":[{"var":"stroke"},["75"]]}]},"message_sv":"Storlek 25 finns med slag 50, 100 eller 150 mm (sida 715).","message_en":"Size 25 exists with strokes 50, 100 or 150 mm (page 715).","goto_step":"lesh-stroke"},{"severity":"error","if_json":{"and":[{"==":[{"var":"lock"},"B"]},{"in":[{"var":"mount"},["R","L"]]},{"in":[{"var":"size"},["8","16"]]},{"==":[{"var":"stroke"},"50"]}]},"message_sv":"Låset B finns inte på R/L-typ i storlek 8 och 16 vid 50 mm slag — välj längre slag eller D-typ (sida 715, tabellen).","message_en":"The lock B is not available on the R/L type in size 8 and 16 at 50 mm stroke — choose a longer stroke or the D type (page 715, chart).","goto_step":"lesh-lock"},{"severity":"error","if_json":{"and":[{"==":[{"var":"holder"},"H"]},{"!=":[{"var":"mount"},"D"]}]},"message_sv":"Sidohållaren H finns bara för D-typen (sida 715).","message_en":"The side holder H exists only for the D type (page 715).","goto_step":"lesh-holder"},{"severity":"error","if_json":{"and":[{"in":[{"var":"cable"},["S1","S3","S5"]]},{"!=":[{"var":"motor"},""]}]},"message_sv":"Standardkabeln S1/S3/S5 finns bara för stegmotorn (inkrementell); servomotorn och den absoluta stegmotorn beställs med robotkabel R (sida 705 och 715, not 8).","message_en":"The standard cable S1/S3/S5 exists only for the step motor (incremental); the servo motor and the absolute step motor are ordered with the robotic cable R (pages 705 and 715, note 8).","goto_step":"lesh-cable"},{"severity":"warn","if_json":{"in":[{"var":"cable"},["R8","RA","RB","RC"]]},"message_sv":"Robotkabel R8/RA/RB/RC (8–20 m) tillverkas på beställning; över 5 m sjunker hastighet och kraft med upp till 10 % per 5 m (sida 715, not 5, och 718, not 3).","message_en":"Robotic cable R8/RA/RB/RC (8–20 m) is produced upon receipt of order; above 5 m speed and force drop by up to 10 % per 5 m (page 715, note 5, and 718, note 3).","goto_step":"lesh-cable"},{"severity":"info","if_json":{"in":[{"var":"cable"},["S1","S3","S5"]]},"message_sv":"Standardkabeln används bara på fasta delar; på rörliga delar väljs robotkabel (sida 715, not 6).","message_en":"The standard cable is used only on fixed parts; on moving parts choose the robotic cable (page 715, note 6).","goto_step":"lesh-cable"},{"severity":"error","if_json":{"and":[{"==":[{"var":"motor"},""]},{"in":[{"var":"ctrl"},["6N","6P"]]}]},"message_sv":"Till stegmotorn (inkrementell) passar styrenheterna C51, C61, CE1, CEF, C91, C9F, CP1, CPF, CD1, CL1, CLF, CM1, AN och AP, inte 6N och 6P (sida 706 och 716).","message_en":"For the step motor (incremental) the controllers C51, C61, CE1, CEF, C91, C9F, CP1, CPF, CD1, CL1, CLF, CM1, AN and AP fit, not 6N and 6P (pages 706 an