insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-LESH-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"info","if_json":{"and":[{"==":[{"var":"size"},"25"]},{"==":[{"var":"motor"},"E"]},{"==":[{"var":"lead"},"K"]}]},"message_sv":"Storlek 25, stigning 8 mm, den batterilösa absoluta stegmotorn: last 12 kg horisontellt/4 kg vertikalt, tryckkraft 77–180 N, 10–150 mm/s; lås 500 N; motor 42 (sida 707).","message_en":"Size 25, lead 8 mm, the battery-less absolute step motor: load 12 kg horizontal/4 kg vertical, pushing force 77–180 N, 10–150 mm/s; lock 500 N; motor 42 (page 707).","goto_step":"lesh-lead"},{"severity":"info","if_json":{"!=":[{"var":"size"},""]},"message_sv":"LESH: repeternoggrannhet ±0,05 mm, max 5000 mm/s², 5–40 °C, IP30, 24 V DC; glidskruv med rem (R/L) eller direkt (D), cirkulerande linjärstyrning; aktuator och styrenhet säljs som ett paket (sida 716 och 718).","message_en":"LESH: positioning repeatability ±0.05 mm, max 5000 mm/s², 5–40 °C, IP30, 24 V DC; slide screw with belt (R/L) or direct (D), circulating linear guide; actuator and controller are sold as a package (pages 716 and 718).","goto_step":"lesh-size"},{"severity":"info","if_json":{"==":[{"var":"body"},"S"]},"message_sv":"Dammskyddad S: R/L-typ får avstrykare på stångkåpan och packningar i båda ändkåporna (IP5X-ekvivalent); D-typ får avstrykare på stångkåpan (sida 716, not 3).","message_en":"Dust-protected S: the R/L type gets a scraper on the rod cover and gaskets in both end covers (IP5X equivalent); the D type gets a scraper on the rod cover (page 716, note 3).","goto_step":"lesh-body"}]'::jsonb) r;

insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-lesh.pdf', 'lesh', 'SMC — SMC Slide Tables LES/LESH Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  description = 'Electric slide table, high rigidity type with linear guide. Sizes 8/16/25, strokes 50–150 mm, ±0.05 mm, step motor (incremental or battery-less absolute) or servo motor 24 VDC, JXC/LEC controllers.'
where sku = 'SMC-LESH';

update product_specs s set value = '50–150 (storlek 8: 50/75, 16: 50/100, 25: 50/100/150)'
from products p where s.product_id = p.id and p.sku = 'SMC-LESH' and s.key = 'stroke_mm';

update product_specs s set value = '±0.05'
from products p where s.product_id = p.id and p.sku = 'SMC-LESH' and s.key = 'repeatability_mm';

update product_specs s set value = 'Stegmotor 24 V DC (inkrementell eller batterilös absolut) eller servomotor 24 V DC'
from products p where s.product_id = p.id and p.sku = 'SMC-LESH' and s.key = 'drive';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('size', '8, 16, 25'),
  ('lead_mm', '4/8, 5/10, 8/16'),
  ('max_speed_mm_s', '400'),
  ('ip_rating', 'IP30'),
  ('temp_range', '5 to 40'),
  ('order_code_example', 'LESH25REJ-50-R1CD17T'),
  ('catalogue', 'SMC LES/LESH, How to Order sida 705 (absolut) och 715 (inkrementell), styrenheter 706/716, data 707/718/719')
) as x(key, value)
where p.sku = 'SMC-LESH'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

